using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Appearance;

// Retains only the visible 5x5 chunks. Changing camera/quality cannot mutate Core.
public partial class ContinuousTerrainRenderer:Node3D
{
 readonly Dictionary<string,Node3D> chunks=new();readonly SceneryVisualAssets assets=new();
 public bool Improved=true;public string Skin{get;private set;}="skin:baseline";public void SetSkin(string id){if(!assets.Catalog.Skins.Any(s=>s.Id==id))throw new ArgumentException("Unknown skin");Skin=id;}public int PackedAssetCount=>chunks.Values.Sum(n=>n.GetMeta("packed",0).AsInt32());public string[] Notices=>assets.Notices.OrderBy(x=>x,StringComparer.Ordinal).ToArray();public int Resident=>chunks.Count;public int Created;public int Evicted;public int Triangles=>chunks.Count*512;public string[] TileIds=>chunks.Keys.OrderBy(x=>x,StringComparer.Ordinal).ToArray();
 public readonly List<(Vector3 A,Vector3 B,Vector3 C)> Picks=new();
 public bool RoadTexturePreserved{get{var visual=SceneryAppearance.Resolve(assets.Catalog,Skin,SceneryAppearance.Appearance("surface/road"));var texture=assets.Material(visual.Material,true).AlbedoTexture;return texture!=null&&Mat("road").AlbedoTexture?.GetInstanceId()==texture.GetInstanceId();}}
 readonly Dictionary<string,StandardMaterial3D> mats=new();string? builtQuality;
 StandardMaterial3D Mat(string kind){string key=kind+Improved+Skin;if(mats.TryGetValue(key,out var m))return m;string role=kind=="outside"?"surface/water":"surface/"+kind;var v=SceneryAppearance.Resolve(assets.Catalog,Skin,SceneryAppearance.Appearance(role));m=(StandardMaterial3D)assets.Material(v.Material,true).Duplicate();m.VertexColorUseAsAlbedo=true;m.AlbedoColor=Colors.White;m.Roughness=1;if(Improved&&m.AlbedoTexture==null){var image=Image.CreateEmpty(64,64,false,Image.Format.Rgb8);for(int x=0;x<64;x++)for(int y=0;y<64;y++){uint textureSeed=SceneryAppearance.StableSeed($"texture/{x}/{y}");float g=.82f+(textureSeed%100)*.0018f;image.SetPixel(x,y,new Color(g,g*.98f,g*.94f));}m.AlbedoTexture=ImageTexture.CreateFromImage(image);m.Uv1Scale=Vector3.One;}mats[key]=m;return m;}
 Color Color(string kind){var v=SceneryAppearance.Resolve(assets.Catalog,Skin,SceneryAppearance.Appearance("surface/"+(kind=="outside"?"water":kind)));return assets.Color(v.Material);}
 Vector3 Relative(SceneryVertex v,FieldPoint o)=>new((v.Point.X-o.X)/1000f,v.HeightMm/1000f,-(v.Point.Y-o.Y)/1000f);
 void Mesh(Node3D root,Mesh mesh,Color color,Vector3 p,Vector3? rotation=null){root.AddChild(new MeshInstance3D{Mesh=mesh,Position=p,Rotation=rotation??Vector3.Zero,MaterialOverride=new StandardMaterial3D{AlbedoColor=color,Roughness=1}});}
 Node3D Build(TerrainTile tile){var root=new Node3D{Name="Chunk"};int packed=0;var o=ContinuousWorld.Point(tile.Node,tile.X*ContinuousWorld.Tile,tile.Y*ContinuousWorld.Tile);var surfaces=new Dictionary<string,SurfaceTool>();foreach(var t in ContinuousWorld.Surfaces(tile)){if(!surfaces.TryGetValue(t.Kind,out var st)){st=new();st.Begin(Godot.Mesh.PrimitiveType.Triangles);surfaces[t.Kind]=st;}var a=Relative(t.A,o);var b=Relative(t.B,o);var c=Relative(t.C,o);int n=2;Vector3 At(int i,int j)=>a+(b-a)*(i/(float)n)+(c-a)*(j/(float)n);void V(Vector3 p){var wp=new FieldPoint(o.X+(long)(p.X*1000),o.Y-(long)(p.Z*1000));uint seed=SceneryAppearance.StableSeed($"{wp.X/2500}/{wp.Y/2500}");var color=Color(t.Kind);float shade=Improved?.91f+(seed%20)*.006f:1;st.SetColor(color*shade);st.SetUV(new((wp.X-ContinuousWorld.Origin(tile.Node).X)/3000f,(wp.Y-ContinuousWorld.Origin(tile.Node).Y)/3000f));st.AddVertex(p);}for(int i=0;i<n;i++)for(int j=0;j<n-i;j++){V(At(i,j));V(At(i+1,j));V(At(i,j+1));if(i+j<n-1){V(At(i+1,j));V(At(i+1,j+1));V(At(i,j+1));}}if(t.Kind=="cliff"&&t.B.Point.Y==t.A.Point.Y){var min=new FieldPoint(new[]{t.A.Point.X,t.B.Point.X,t.C.Point.X}.Min(),new[]{t.A.Point.Y,t.B.Point.Y,t.C.Point.Y}.Min());var max=new FieldPoint(min.X+10000,min.Y+10000);var cp=new FieldPoint(min.X+5000,min.Y+5000);uint seed=SceneryAppearance.StableSeed($"world/rock:{min.X/10000}/{min.Y/10000}");var placement=new SceneryPlacement($"world/rock:{min.X/10000}/{min.Y/10000}","rock","rock",SceneryAppearance.Appearance("rock"),cp,min,max,6000,6000,4000,(int)(seed%360)*1000,seed%2==0?"variant:a":"variant:b",seed);var visual=SceneryAppearance.Resolve(assets.Catalog,Skin,SceneryAppearance.Appearance("rock"));Node3D? model=null;while(visual.Builder=="scene"){model=assets.Instantiate(visual,placement);if(model!=null)break;visual=assets.Catalog.Visuals.Single(v=>v.Id==visual.Fallback);}var p=Relative(new(cp,ContinuousWorld.Height(cp)),o);if(model!=null){model.Position=p;root.AddChild(model);packed++;}else Mesh(root,new SphereMesh{Radius=3,Height=4,RadialSegments=Improved?8:5,Rings=Improved?4:2},assets.Color(visual.Material),p+Vector3.Up*2);}}

 foreach(var (kind,st) in surfaces){st.GenerateNormals();root.AddChild(new MeshInstance3D{Mesh=st.Commit(),MaterialOverride=Mat(kind)});}
 foreach(var ob in ContinuousWorld.Obstacles(ContinuousWorld.Nearest(o))){var cp=new FieldPoint((ob.Min.X+ob.Max.X)/2,(ob.Min.Y+ob.Max.Y)/2);if(ContinuousWorld.TileAt(cp)!=tile)continue;var p=new Vector3((cp.X-o.X)/1000f,ContinuousWorld.Height(cp)/1000f,-(cp.Y-o.Y)/1000f);float w=(ob.Max.X-ob.Min.X)/1000f,d=(ob.Max.Y-ob.Min.Y)/1000f,h=ob.HeightMm/1000f;var role=ob.Kind;if(role!="tree"){var heights=new[]{ob.Min,ob.Max,new FieldPoint(ob.Min.X,ob.Max.Y),new FieldPoint(ob.Max.X,ob.Min.Y)}.Select(ContinuousWorld.Height).ToArray();p.Y=heights.Min()/1000f;h+=(heights.Max()-heights.Min())/1000f;}var visual=SceneryAppearance.Resolve(assets.Catalog,Skin,SceneryAppearance.Appearance(role));var placement=new SceneryPlacement(tile.Node+"/"+ob.Id,ob.Id,role,SceneryAppearance.Appearance(role),cp,ob.Min,ob.Max,(int)(w*1000),(int)(d*1000),(int)(h*1000),0,"variant:a",SceneryAppearance.StableSeed(ob.Id));if(visual.Builder=="scene"){var model=assets.Instantiate(visual,placement);if(model!=null){model.Position=p;root.AddChild(model);packed++;continue;}}
 if(role=="tree"){Mesh(root,new CylinderMesh{TopRadius=.35f,BottomRadius=.5f,Height=h,RadialSegments=6},assets.Color("material:tree"),p+Vector3.Up*h/2);for(int i=0;i<(Improved?3:1);i++)Mesh(root,new SphereMesh{Radius=2.8f-i*.5f,Height=4.2f,RadialSegments=7,Rings=3},assets.Color(i%2==0?"material:pine-dark":"material:pine-mid"),p+Vector3.Up*(h-3+i*1.6f),new Vector3(0,i*.17f,0));}else if(role=="keep"){Mesh(root,new BoxMesh{Size=new(w,h*.65f,d)},assets.Color("material:keep"),p+Vector3.Up*h*.325f);Mesh(root,new PrismMesh{Size=new(w+2,h*.35f,d+2)},assets.Color("material:roof-lower"),p+Vector3.Up*h*.825f);if(Improved){Mesh(root,new BoxMesh{Size=new(w*.6f,3,d*.6f)},assets.Color("material:plaster"),p+Vector3.Up*(h+1));Mesh(root,new PrismMesh{Size=new(w*.7f,2,d*.7f)},assets.Color("material:roof-upper"),p+Vector3.Up*(h+3.5f));}}else{Mesh(root,new BoxMesh{Size=new(w,h,d)},assets.Color("material:wall"),p+Vector3.Up*h/2);}}
 root.SetMeta("packed",packed);return root;}
 public void Update(FieldPoint center,double span){string buildKey=Improved+Skin;if(builtQuality!=buildKey){assets.Notices.Clear();foreach(var n in chunks.Values){RemoveChild(n);n.Free();}chunks.Clear();builtQuality=buildKey;}var tiles=ContinuousWorld.VisibleTiles(center,span);var wanted=tiles.Select(t=>t.Id).ToHashSet(StringComparer.Ordinal);foreach(var id in chunks.Keys.Where(k=>!wanted.Contains(k)).ToArray()){var n=chunks[id];RemoveChild(n);n.Free();chunks.Remove(id);Evicted++;}Picks.Clear();foreach(var tile in tiles){if(!chunks.TryGetValue(tile.Id,out var chunk)){chunk=Build(tile);AddChild(chunk);chunks[tile.Id]=chunk;Created++;}var o=ContinuousWorld.Point(tile.Node,tile.X*ContinuousWorld.Tile,tile.Y*ContinuousWorld.Tile);chunk.Position=new((o.X-center.X)/1000f,0,-(o.Y-center.Y)/1000f);foreach(var t in ContinuousWorld.Surfaces(tile))Picks.Add((Relative(t.A,center),Relative(t.B,center),Relative(t.C,center)));}if(chunks.Count>25)throw new Exception("Resident chunk budget exceeded");}
}
